//! Parsed inert sources receive their eventual native IDs before publication.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><div id=mount></div><input id=field value=seed></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://parsed-identities.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn domparser_node_identity_saved_nodes_attrs_lists_and_both_observers_survive_direct_insertion(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var owner=new DOMParser().parseFromString('<!doctype html><html><head><title>source</title></head><body><div id="parsed" data-note="held"><span>real parsed data</span><!--marker--></div></body></html>','text/html'),root=owner.body.firstChild,child=root.firstChild,text=child.firstChild,marker=root.lastChild,attr=root.getAttributeNode('data-note'),list=root.childNodes,view=root.children,sourceList=owner.body.childNodes,mount=document.getElementById('mount'),state={held:root},old=new MutationObserver(function(){}),next=new MutationObserver(function(){});root.bindingState=state;old.observe(owner,{subtree:true,childList:true});next.observe(mount,{childList:true});
if(owner.doctype.name!=='html'||owner.doctype.ownerDocument!==owner||owner.documentElement.ownerDocument!==owner||owner.head.nextSibling!==owner.body||owner.URL!=='https://parsed-identities.test/source'||owner.title!=='source'||root.ownerDocument!==owner||child.ownerDocument!==owner||text.ownerDocument!==owner)throw 'actual projected parser document metadata';
if(mount.appendChild(root)!==root||root.ownerDocument!==document||root.parentNode!==mount||root.firstChild!==child||child.firstChild!==text||root.lastChild!==marker||root.getAttributeNode('data-note')!==attr||attr.ownerDocument!==document||root.childNodes!==list||root.children!==view||list[0]!==child||list[1]!==marker||view[0]!==child||root.bindingState!==state||state.held!==root||sourceList.length!==0||owner.body.firstChild!==null||root.textContent!=='real parsed data')throw 'same parsed IDs directly promoted';
var removed=old.takeRecords(),added=next.takeRecords();if(removed.length!==1||removed[0].target!==owner.body||removed[0].removedNodes[0]!==root||added.length!==1||added[0].target!==mount||added[0].addedNodes[0]!==root)throw 'actual projected source/destination records';
"#);
}
#[test]
fn domparser_node_identity_resource_nonce_and_template_guards_remain_real(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"
var parser=new DOMParser(),owner=parser.parseFromString('<!doctype html><html><head><script nonce="private">window.parserEscaped=true;</script></head><body><img src="https://no-parser-activation.test/image.png"><p>safe</p></body></html>','text/html'),script=owner.head.firstChild,image=owner.body.firstChild,safe=owner.body.lastChild,mount=document.getElementById('mount'),caught=false;
if(owner.defaultView!==null||typeof window.parserEscaped!=='undefined'||script.ownerDocument!==owner||image.ownerDocument!==owner||safe.ownerDocument!==owner)throw 'parser sources remain inert';try{mount.appendChild(script);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||script.parentNode!==owner.head||script.ownerDocument!==owner||typeof window.parserEscaped!=='undefined'||mount.childNodes.length)throw 'script cannot gain native capability through projection';caught=false;try{mount.appendChild(image);}catch(e){caught=e instanceof DOMException&&e.name==='NotSupportedError';}if(!caught||image.parentNode!==owner.body||image.ownerDocument!==owner||mount.childNodes.length)throw 'resource lifecycle remains guarded';if(mount.appendChild(safe)!==safe||safe.ownerDocument!==document||owner.body.childNodes.length!==1||owner.body.firstChild!==image||safe.textContent!=='safe')throw 'only actual safe source promoted';
"#);run(&mut doc,&mut forms,&mut page,"var templateDocument=parser.parseFromString('<template><span>guarded</span></template>','text/html'),template=templateDocument.querySelector('template'),content=template.content;if(template.ownerDocument!==templateDocument||template.childNodes.length||content.firstChild.textContent!=='guarded'||content.ownerDocument===templateDocument||content.ownerDocument===document||content.isConnected||content.parentNode!==null)throw 'separate inert parsed template';");assert!(!page.has_navigation_request());assert!(page.take_dynamic_scripts().is_empty()&&page.take_dynamic_stylesheets().is_empty());let(a,b,c)=page.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
